{"component_id":"component-86dd47640b4a","code":"def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count range values ending with s whose decimal digits are all <= limit."""
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    place = 10 ** len(s)
    zero_prefix_is_valid = s[0] != "0" and suffix_value > 0

    def count_prefixes_at_most(bound: int) -> int:
        """Number of nonnegative prefix integers <= bound with allowed digits."""
        if bound < 0:
            return 0
        digits = str(bound)
        ways_tight, ways_loose = 1, 0
        for ch in digits:
            digit = int(ch)
            new_loose = ways_loose * (limit + 1)
            new_tight = ways_tight * (min(limit, digit) + 1)
            if digit > limit:
                new_loose += ways_tight * (digit - limit)
            ways_tight, ways_loose = new_tight, new_loose
        count = ways_tight + ways_loose
        # The all-zero prefix corresponds to the suffix alone. If its string
        # begins with zero, concatenation would have a leading zero instead.
        if not zero_prefix_is_valid:
            count -= 1
        return count

    def count_upto(bound: int) -> int:
        if bound < suffix_value:
            return 0
        max_prefix = (bound - suffix_value) // place
        return count_prefixes_at_most(max_prefix)

    return count_upto(finish) - count_upto(start - 1)"}
